  "resolution": "func (c *Context) IsSet(name string) bool {
    if c.setFlags == nil {
        c.setFlags = make(map[string]bool)

        c.flagSet.Visit(func(f *flag.Flag) {
            c.setFlags[f.Name] = true
        })

        c.flagSet.VisitAll(func(f *flag.Flag) {
            if _, ok := c.setFlags[f.Name]; ok {
